// for forward compatibility.
//
// ==============================================================================
// NoxChatControlService
// Full control plane for NoxAI / NoxChat node administration, telemetry,
// direct interaction, memories, libraries, raw API payloads, and jobs.
// ==============================================================================
type NoxChatControlServiceServer interface {
	// Handshake, Node Info, Transport Compression Stats, and Live Config
	GetNodeStatus(context.Context, *NoxNodeStatusRequest) (*NoxNodeStatusResponse, error)
	UpdateControlConfig(context.Context, *NoxUpdateControlConfigRequest) (*NoxNodeStatusResponse, error)
	// Asynchronous Zstd-Chunked Live Streams (1MB State/Telemetry Buffer / 8MB Log/API Buffer)
	SubscribeState(*NoxStateSubscriptionRequest, grpc.ServerStreamingServer[NoxStateChunk]) error
	SubscribeLogsAndApi(*NoxLogApiSubscriptionRequest, grpc.ServerStreamingServer[NoxLogApiChunk]) error
	// Historical Usage & Python Runtime Telemetry Query (LTTB Downsampled for MetricHistoryChartControl)
	QueryTelemetryRange(context.Context, *RangeQueryRequest) (*RangeQueryResponse, error)
	// Historical Spool Paging (from 1GB Server-Side WAL Spool when store_raw_logs is enabled)
	GetSpoolStats(context.Context, *NoxSpoolStatsRequest) (*NoxSpoolStatsResponse, error)
	QueryLogChunks(context.Context, *LogChunkQuery) (*LogChunkResponse, error)
	QueryApiCallChunks(context.Context, *NoxApiCallChunkQuery) (*NoxApiCallChunkResponse, error)
	GetApiCallDetail(context.Context, *NoxApiCallDetailRequest) (*NoxRawApiCallRecord, error)
	ClearSpool(context.Context, *NoxClearSpoolRequest) (*NoxClearSpoolResponse, error)
	// Direct Chat Interaction (User: "MADTOM", UserID: "Control Center")
	SendDirectMessage(*NoxDirectMessageRequest, grpc.ServerStreamingServer[NoxDirectTurnEvent]) error
	GetChatHistory(context.Context, *NoxChatHistoryRequest) (*NoxChatHistoryResponse, error)
	ListChats(context.Context, *NoxListChatsRequest) (*NoxListChatsResponse, error)
	// RAG, Atomic Memories & Hot Memory Inspection + Modification
	QueryMemories(context.Context, *NoxMemoryQueryRequest) (*NoxMemoryQueryResponse, error)
	SearchMemoriesHybrid(context.Context, *NoxHybridSearchRequest) (*NoxHybridSearchResponse, error)
	UpsertMemory(context.Context, *NoxUpsertMemoryRequest) (*NoxMemoryMutationResponse, error)
	DeleteMemory(context.Context, *NoxDeleteMemoryRequest) (*NoxMemoryMutationResponse, error)
	ListHotMemories(context.Context, *NoxHotMemoryRequest) (*NoxHotMemoryResponse, error)
	UpsertHotMemory(context.Context, *NoxUpsertHotMemoryRequest) (*NoxHotMemoryResponse, error)
	DeleteHotMemory(context.Context, *NoxDeleteHotMemoryRequest) (*NoxHotMemoryResponse, error)
	// Stickers, GIFs, Libraries & Vector Inspection + Modification
	QueryMediaLibrary(context.Context, *NoxMediaQueryRequest) (*NoxMediaQueryResponse, error)
	GetMediaAssetPreview(context.Context, *NoxMediaPreviewRequest) (*NoxMediaPreviewResponse, error)
	MutateMediaItem(context.Context, *NoxMediaMutationRequest) (*NoxMediaMutationResponse, error)
	ManageMediaPin(context.Context, *NoxMediaPinRequest) (*NoxMediaMutationResponse, error)
	TriggerStickerPackAnalysis(context.Context, *NoxAnalyzePackRequest) (*NoxAnalyzePackResponse, error)
	ForceAddSticker(context.Context, *NoxForceAddStickerRequest) (*NoxMediaMutationResponse, error)
	// Active Jobs & Vector Store Explorer
	GetActiveJobs(context.Context, *NoxActiveJobsRequest) (*NoxActiveJobsResponse, error)
	InspectVectors(context.Context, *NoxVectorInspectRequest) (*NoxVectorInspectResponse, error)
	// User Profiles & Avatars
	QueryUserProfiles(context.Context, *NoxUserProfileQueryRequest) (*NoxUserProfileQueryResponse, error)
	SearchUserProfiles(context.Context, *NoxUserProfileSearchRequest) (*NoxUserProfileSearchResponse, error)
	GetUserProfilePhoto(context.Context, *NoxUserProfilePhotoRequest) (*NoxUserProfilePhotoResponse, error)
	mustEmbedUnimplementedNoxChatControlServiceServer()
}

